  <!-- Google Çeviri motorunun bağlanacağı kap. Kendi dil seçicimizi
       kullandığımız için görsel olarak gizli (CSS: ttp-base.css). -->
  <div id="google_translate_element" aria-hidden="true"></div>
  <script id="ttp-lang-switcher-js">
    // Header dil seçici + Google Çeviri entegrasyonu.
    // Seçilen dil `googtrans` çerezine yazılır; Google widget'ı sayfa
    // açılışında bu çerezi okuyup çeviriyi kendiliğinden uygular, böylece
    // seçim sayfalar arasında korunur.
    (function () {
      'use strict';

      var SOURCE_LANG = 'tr';
      var COOKIE_NAME = 'googtrans';

      var switcher = document.getElementById('ttpLangSwitcher');
      var btn = document.getElementById('ttpLangBtn');
      var dropdown = document.getElementById('ttpLangDropdown');
      if (!switcher || !btn || !dropdown) return;

      var options = Array.prototype.slice.call(dropdown.querySelectorAll('.ttp-lang-option'));
      var includedLanguages = options
        .map(function (o) { return o.getAttribute('data-lang'); })
        .filter(function (l) { return l && l !== SOURCE_LANG; })
        .join(',');

      /* ---------- Çerez yardımcıları ----------
         googtrans biçimi: /<kaynak>/<hedef>  (örn. /tr/en)
         Google çerezi hem `host` hem `.host` üzerinde arayabildiği için
         her ikisine de yazıyoruz; aksi halde alt alan adlarında seçim
         sayfa değişince kayboluyor. */
      function cookieDomains() {
        var host = location.hostname;
        var list = [''];
        if (host && host.indexOf('.') > -1 && !/^[0-9.]+$/.test(host)) {
          list.push('.' + host);
          var bare = host.replace(/^www\./, '');
          if (bare !== host) list.push('.' + bare);
        }
        return list;
      }

      function writeCookie(value, maxAge) {
        cookieDomains().forEach(function (domain) {
          document.cookie = COOKIE_NAME + '=' + value + ';path=/;max-age=' + maxAge +
            (domain ? ';domain=' + domain : '') + ';SameSite=Lax';
        });
      }

      function setTranslation(lang) { writeCookie('/' + SOURCE_LANG + '/' + lang, 31536000); }
      function clearTranslation() { writeCookie('', 0); }

      function activeLang() {
        var m = document.cookie.match(/(?:^|;\s*)googtrans=([^;]*)/);
        if (!m || !m[1]) return SOURCE_LANG;
        var parts = decodeURIComponent(m[1]).split('/');
        return parts[2] || SOURCE_LANG;
      }

      /* ---------- Buton görünümünü seçili dille eşitle ---------- */
      function syncButton(lang) {
        var opt = null, fallback = null, i;
        for (i = 0; i < options.length; i++) {
          var code = options[i].getAttribute('data-lang');
          if (code === lang) opt = options[i];
          if (code === SOURCE_LANG) fallback = options[i];
        }
        opt = opt || fallback;
        if (!opt) return;

        for (i = 0; i < options.length; i++) {
          if (options[i] === opt) options[i].classList.add('active');
          else options[i].classList.remove('active');
        }

        var srcFlag = opt.querySelector('.ttp-flag-icon');
        var btnFlag = btn.querySelector('.ttp-flag-icon');
        if (srcFlag && btnFlag) btnFlag.innerHTML = srcFlag.innerHTML;

        var btnCode = btn.querySelector('.ttp-lang-code');
        if (btnCode) {
          btnCode.textContent = (opt.getAttribute('data-lang') || SOURCE_LANG)
            .split('-')[0].toUpperCase();
        }
      }

      /* ---------- Google Çeviri widget'ı ---------- */
      var widgetRequested = false;

      window.ttpGoogleTranslateInit = function () {
        if (!window.google || !window.google.translate || !google.translate.TranslateElement) return;
        new google.translate.TranslateElement({
          pageLanguage: SOURCE_LANG,
          includedLanguages: includedLanguages,
          autoDisplay: false
        }, 'google_translate_element');
      };

      function loadWidget() {
        if (widgetRequested) return;
        widgetRequested = true;
        var s = document.createElement('script');
        s.src = 'https://translate.google.com/translate_a/element.js?cb=ttpGoogleTranslateInit';
        s.async = true;
        document.body.appendChild(s);
      }

      // Widget'ın gizli <select>'ini tetiklemek sayfayı yeniden yüklemeden
      // çeviriyi uygular. Hazır değilse kısa süre bekleyip yenilemeye düşeriz.
      function applyLang(lang) {
        var combo = document.querySelector('select.goog-te-combo');
        if (!combo) return false;
        combo.value = lang;
        combo.dispatchEvent(new Event('change', { bubbles: true }));
        return true;
      }

      function selectLang(lang) {
        if (!lang || lang === activeLang()) return;

        if (lang === SOURCE_LANG) {
          // Türkçeye dönüş: çeviriyi tamamen kaldırmanın tek güvenilir yolu
          // çerezi silip sayfayı yeniden yüklemek.
          clearTranslation();
          location.reload();
          return;
        }

        setTranslation(lang);
        syncButton(lang);
        loadWidget();

        var tries = 0;
        (function attempt() {
          if (applyLang(lang)) return;
          if (++tries > 20) { location.reload(); return; }
          setTimeout(attempt, 150);
        })();
      }

      /* ---------- Açılır menü davranışı ---------- */
      function closeMenu() {
        switcher.classList.remove('is-open');
        btn.setAttribute('aria-expanded', 'false');
      }

      btn.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        var isOpen = switcher.classList.toggle('is-open');
        btn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
      });

      document.addEventListener('click', function (e) {
        if (!switcher.contains(e.target)) closeMenu();
      });

      document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') closeMenu();
      });

      options.forEach(function (opt) {
        opt.addEventListener('click', function (e) {
          e.preventDefault();
          e.stopPropagation();
          closeMenu();
          selectLang(opt.getAttribute('data-lang'));
        });
      });

      /* ---------- Açılış durumu ---------- */
      var current = activeLang();
      syncButton(current);

      if (current !== SOURCE_LANG) {
        // Çeviri aktif: widget'ı hemen yükle ki çerezdeki dil uygulansın.
        loadWidget();
      } else {
        // Türkçe ziyaretçiyi bekletmemek için widget'ı sayfa yüklendikten
        // sonra, boşta yükle.
        window.addEventListener('load', function () { setTimeout(loadWidget, 1500); });
      }
    })();
  </script>
  <script id="ttp-search-js">
    // Arama katmanı. ElementsKit'in kendi modalı (magnific-popup) bu statik
    // kurulumda hiç açılmıyor; bağımsız ve bağımlılıksız bir uygulama.
    (function () {
      var openBtn = document.querySelector('.ttp-search-open');
      var overlay = document.getElementById('ttp-search-overlay');
      if (!openBtn || !overlay) return;

      var input = overlay.querySelector('.ttp-search-input');
      var closeBtn = overlay.querySelector('.ttp-search-close');

      function open() {
        overlay.hidden = false;
        openBtn.setAttribute('aria-expanded', 'true');
        document.body.style.overflow = 'hidden';
        if (input) input.focus();
      }

      function close() {
        overlay.hidden = true;
        openBtn.setAttribute('aria-expanded', 'false');
        document.body.style.overflow = '';
        openBtn.focus();
      }

      openBtn.addEventListener('click', open);
      if (closeBtn) closeBtn.addEventListener('click', close);

      // Karartılmış alana tıklayınca kapansın (formun kendisine tıklayınca değil).
      overlay.addEventListener('click', function (e) {
        if (e.target === overlay) close();
      });

      document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape' && !overlay.hidden) close();
      });

      // Boş aramayla /haberler/ sayfasına gitmenin anlamı yok.
      overlay.querySelector('.ttp-search-form').addEventListener('submit', function (e) {
        if (!input.value.trim()) e.preventDefault();
      });
    })();
  </script>
  <!-- Yönetim Kurulu Yatay Pürüzsüz Kaydırma (Drag & Scroll) Motoru -->
  <script id="ttp-team-horizontal-scroll">
    (function () {
      function initTeamCarousel() {
        var slider = document.querySelector('.ttp-team-grid');
        var prevBtn = document.getElementById('ttp-team-prev-btn');
        var nextBtn = document.getElementById('ttp-team-next-btn');
        if (!slider) return;

        // 1. Mouse Drag to Scroll (İmleçle basılı tutup pürüzsüz sürükleme)
        var isDown = false;
        var startX = 0;
        var scrollLeft = 0;

        slider.addEventListener('mousedown', function (e) {
          isDown = true;
          slider.classList.add('is-dragging');
          startX = e.pageX - slider.offsetLeft;
          scrollLeft = slider.scrollLeft;
        });

        window.addEventListener('mouseup', function () {
          if (isDown) {
            isDown = false;
            slider.classList.remove('is-dragging');
          }
        });

        window.addEventListener('mousemove', function (e) {
          if (!isDown) return;
          e.preventDefault();
          var x = e.pageX - slider.offsetLeft;
          var walk = (x - startX) * 1.5;
          slider.scrollLeft = scrollLeft - walk;
        });

        slider.addEventListener('dragstart', function (e) {
          e.preventDefault();
        });

        // 2. Butonlarla Kaydırma (İleri - Geri Ok Butonları)
        var scrollStep = 360;
        if (prevBtn) {
          prevBtn.addEventListener('click', function (e) {
            e.preventDefault();
            slider.scrollBy({ left: -scrollStep, behavior: 'smooth' });
          });
        }
        if (nextBtn) {
          nextBtn.addEventListener('click', function (e) {
            e.preventDefault();
            slider.scrollBy({ left: scrollStep, behavior: 'smooth' });
          });
        }
      }

      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initTeamCarousel);
      } else {
        initTeamCarousel();
      }
    })();
  </script>
